def transform(grid):
    g=[row[:] for row in grid]
    pts=[]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v: pts.append((r,c,v))
    # For each colored marker, extend in cardinal directions toward nearest point:
    # 1/2/3 points generate a 3-cell L-like mark in color 5 beside the marker.
    # Based on demos, each marker extends toward the other along its row or column.
    if len(pts)==2:
        (r1,c1,v1),(r2,c2,v2)=pts
        if v1==1: # 1 reaches two cells toward marker 2, then turns one toward it
            if r1==r2:
                for c in range(min(c1,c2)+1,max(c1,c2)): g[r1][c]=5
            elif c1==c2:
                for r in range(min(r1,r2)+1,max(r1,r2)): g[r][c1]=5
            else:
                dr=1 if r2>r1 else -1; dc=1 if c2>c1 else -1
                # stair-step direction, as exemplified
                for k in range(1,min(abs(r2-r1),abs(c2-c1))+1):
                    if g[r1+dr*k][c1+dc*k]==0: g[r1+dr*k][c1+dc*k]=5
        # special branches from marker corners as in examples
        if v1==1 and v2==2:
            # horizontal run from 2 toward 1, and short offset branch from 1
            step=1 if c1>c2 else -1
            for k in range(1,abs(c1-c2)):
                g[r2][c2+step*k]=5
            if r1<r2:
                for k in (1,2):
                    if 0<=r1-1<len(g) and 0<=c1+k<len(g[0]): g[r1-1][c1+k]=5
    return g
