def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    pts={v:(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v}
    if 1 in pts:
        r,c=pts[1]
        # raise a 1 by two columns, with a short colored horizontal connector
        if c+2<w and r>0:
            g[r][c+1]=5; g[r][c+2]=5; g[r-1][c+2]=1
    if 2 in pts:
        r,c=pts[2]
        # 2 connects to a matching 2 four spaces to its left
        if c>=4:
            g[r][c-4]=2
            for x in range(c-3,c):g[r][x]=5
    if 3 in pts:
        r,c=pts[3]
        # matching 3 appears three rows below, joined by two 5s
        if r+3<h:
            g[r+1][c]=5;g[r+2][c]=5;g[r+3][c]=3
    if 6 in pts:
        r,c=pts[6]
        # matching 6 appears six rows above; bridge with 5
        if r>=6:
            g[r-6][c]=6
            for rr in range(r-5,r):g[rr][c]=5
    return g
